using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
class UiRegression {
 static List<string> lines=new List<string>();static Application app;static void Test(string name,bool value){if(!value)throw new Exception(name);lines.Add("PASS: "+name);}
 static object Call(object obj,string method,params object[] args){return obj.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(obj,args);}
 static object Field(object obj,string name){return obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(obj);}
 static IEnumerable<T> Visual<T>(DependencyObject parent)where T:DependencyObject{if(parent is T)yield return(T)parent;for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++)foreach(var child in Visual<T>(VisualTreeHelper.GetChild(parent,i)))yield return child;}
 static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 static void Modal(PremiumPicker owner,Action open,Action<Window> interact){bool acted=false;Exception error=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};int ticks=0;timer.Tick+=(s,e)=>{var dialog=app.Windows.Cast<Window>().FirstOrDefault(x=>x.Owner==owner&&x.IsVisible);if(dialog==null){if(++ticks>150){error=new Exception("Dialog did not appear");timer.Stop();}return;}timer.Stop();try{dialog.UpdateLayout();acted=true;interact(dialog);}catch(Exception ex){error=ex;dialog.Close();}};timer.Start();open();timer.Stop();if(error!=null)throw error;if(!acted)throw new Exception("Modal action not exercised");}
 static void Pump(Task task){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};var timeout=DateTime.UtcNow.AddSeconds(30);timer.Tick+=(s,e)=>{if(task.IsCompleted||DateTime.UtcNow>timeout)frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);timer.Stop();if(!task.IsCompleted)throw new Exception("UI task timed out");task.GetAwaiter().GetResult();}
 [STAThread]static int Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);PremiumPicker owner=null,trayWindow=null;try{app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));var store=new ProfileStore(Path.Combine(root,"profiles"));owner=new PremiumPicker(store,true);owner.Show();owner.UpdateLayout();
  var main=(Grid)owner.Content;var add=(Button)main.FindName("AddTopButton");Modal(owner,()=>Click(add),d=>{Visual<TextBox>(d).First().Text="UI added";Click(Visual<Button>(d).First(x=>x.IsDefault));});var added=store.State.Profiles.Single(x=>x.Name=="UI added");Test("plus-button add dialog saves a persistent profile",new ProfileStore(store.Root).State.Profiles.Any(x=>x.Id==added.Id));string folder=added.Folder;
  var menu=(ContextMenu)Call(owner,"Menu",added.Id);var rename=menu.Items.OfType<MenuItem>().First(x=>(string)x.Header=="Rename profile");Modal(owner,()=>rename.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent)),d=>{Visual<TextBox>(d).First().Text="UI renamed";Click(Visual<Button>(d).First(x=>x.IsDefault));});Test("rename menu changes name and keeps folder",store.State.Profiles.Single(x=>x.Id==added.Id).Name=="UI renamed"&&store.State.Profiles.Single(x=>x.Id==added.Id).Folder==folder);
  menu=(ContextMenu)Call(owner,"Menu",added.Id);menu.Items.OfType<MenuItem>().First(x=>(string)x.Header=="Add to favorites").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Test("favorite menu updates persistent state",new ProfileStore(store.Root).State.Profiles.Single(x=>x.Id==added.Id).Favorite);
  Modal(owner,()=>Call(owner,"IdentityPanel",added.Id),d=>{var text=Visual<TextBox>(d).ToArray();text[0].Text="expected@invalid.example";text[1].Text="qa-workspace";Click(Visual<Button>(d).First(x=>Convert.ToString(x.Content)=="Save identity guard"));});Test("identity settings dialog saves both guards",store.State.Profiles.Single(x=>x.Id==added.Id).ExpectedWorkspace=="qa-workspace");
  Modal(owner,()=>Call(owner,"Customize",added.Id),d=>Click(Visual<Button>(d).Where(x=>x.Width==34).ElementAt(3)));Test("color picker updates profile color",store.State.Profiles.Single(x=>x.Id==added.Id).Color==3);
  string images=Path.Combine(store.Root,"ProfileImages");Directory.CreateDirectory(images);byte[] pixels={200,100,50,255};var bmp=BitmapSource.Create(1,1,96,96,PixelFormats.Bgra32,null,pixels,4);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(Path.Combine(images,"qa-logo.png")))encoder.Save(file);store.Edit(added.Id,p=>p.Logo="qa-logo.png");Call(owner,"Rebuild");owner.UpdateLayout();Test("custom logo loads into a profile card",Visual<Image>(owner).Count()>1);
  Modal(owner,()=>Pump((Task)Call(owner,"RemoveProfile",added.Id)),d=>Click(Visual<Button>(d).First(x=>Convert.ToString(x.Content)=="Remove profile")));Test("remove menu retains account folder metadata and marks removed",store.State.Profiles.Single(x=>x.Id==added.Id).Removed&&store.State.Profiles.Single(x=>x.Id==added.Id).Logo=="qa-logo.png");store.Restore(added.Id);Call(owner,"Rebuild");
  var search=(TextBox)main.FindName("SearchField");search.Text="UI renamed";var cards=(WrapPanel)main.FindName("CardsHost");Test("search retains matched card plus add tile",cards.Children.Count==2);search.Text="no-such-profile";Test("empty search result still offers add profile",cards.Children.Count==1);search.Clear();
  var one=store.Add("Sales/A");var two=store.Add("Sales:A");string shortcutRoot=Path.Combine(root,"shortcuts");string first=PremiumPicker.WriteProfileShortcut(store,one,shortcutRoot,Assembly.GetAssembly(typeof(ProfileStore)).Location);string second=PremiumPicker.WriteProfileShortcut(store,two,shortcutRoot,Assembly.GetAssembly(typeof(ProfileStore)).Location);Test("sanitized shortcut names cannot overwrite another account",first!=second&&File.Exists(first)&&File.Exists(second));Type shellType=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(shellType);dynamic link=shell.CreateShortcut(first);Test("shortcut retains stable profile and store arguments",((string)link.Arguments).Contains(one.Id)&&((string)link.Arguments).Contains(store.Root));System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);
  Call(owner,"Rebuild");owner.SavePreview(Path.Combine(root,"wide.png"));owner.Width=800;owner.Height=700;owner.SavePreview(Path.Combine(root,"compact.png"));Test("wide and compact interfaces render",File.Exists(Path.Combine(root,"compact.png")));
  trayWindow=new PremiumPicker(store,false);trayWindow.Show();trayWindow.UpdateLayout();var icon=Field(trayWindow,"tray")as System.Windows.Forms.NotifyIcon;Test("tray initializes",icon!=null&&icon.Visible);Call(trayWindow,"InitializeFeatures");Test("tray initialization is idempotent",Object.ReferenceEquals(icon,Field(trayWindow,"tray")));bool registered=(bool)Field(trayWindow,"hotkeyRegistered");lines.Add((registered?"PASS: ":"BLOCKED: ")+"global picker hotkey ("+Field(trayWindow,"pickerHotkey")+") registration"+(registered?"":" (Windows error "+Field(trayWindow,"hotkeyError")+")"));trayWindow.Hide();object[] hotArgs={IntPtr.Zero,0x312,new IntPtr(5781),IntPtr.Zero,false};Call(trayWindow,"HotkeyHook",hotArgs);Test("hotkey routing reopens hidden picker",trayWindow.IsVisible);
  var cache=(Dictionary<string,IdentityInfo>)Field(trayWindow,"identities");cache[added.Id]=new IdentityInfo{Email="old@invalid.example",Verified=true,CredentialStamp=AccountService.Stamp(store,added)};string authHome=Path.Combine(store.Root,added.Folder,"codex");Directory.CreateDirectory(authHome);Func<string,string> enc=x=>Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(x)).TrimEnd('=').Replace('+','-').Replace('/','_');string token=enc("{\"alg\":\"none\"}")+"."+enc("{\"email\":\"new@invalid.example\",\"exp\":4102444800}")+".fixture";FeatureJson.Write(Path.Combine(authHome,"auth.json"),new{tokens=new{id_token=token,account_id="different-workspace"}});Pump((Task)Call(trayWindow,"RefreshProcesses"));Test("login refresh removes stale verified identity from UI cache",!cache.ContainsKey(added.Id));Test("UI updates account caption after login file changes",Visual<TextBlock>(trayWindow).Any(x=>x.Text=="new@invalid.example"));
  var task=(Task)Call(trayWindow,"RequestOpen",added.Id);Pump(task);Test("clicking profile while real account is open queues instead of launching",Convert.ToString(Field(trayWindow,"pendingId"))==added.Id);var trayGrid=(Grid)trayWindow.Content;Click((Button)trayGrid.FindName("CancelSwitch"));Test("cancel switch clears queued account",Field(trayWindow,"pendingId")==null);typeof(PremiumPicker).GetField("suppressClickUntil",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(trayWindow,DateTime.UtcNow.AddSeconds(2));Pump((Task)Call(trayWindow,"RequestOpen",added.Id));Test("drag completion suppresses accidental launch clicks",Field(trayWindow,"pendingId")==null);
  trayWindow.Close();trayWindow=null;Test("tray shutdown releases feature resources",true);owner.Close();owner=null;app.Shutdown();return 0;
 }catch(Exception ex){lines.Add(ex.ToString());return 1;}finally{if(trayWindow!=null)trayWindow.Close();if(owner!=null)owner.Close();File.WriteAllLines(Path.Combine(root,"ui-results.txt"),lines);foreach(string line in lines)Console.WriteLine(line);}}
}
